window.SANTEJUSTE_BACKLOG_AUDITED = window.SANTEJUSTE_BACKLOG_AUDITED || [];
window.SANTEJUSTE_BACKLOG_AUDITED.push({
  id: "perimenopause-signes-quand-consulter",
  category: "Santé des femmes",
  question: "Suis-je en préménopause ? Quels sont les signes et quand consulter ?",
  shortAnswer: "La périménopause est une transition naturelle qui précède la ménopause. Elle débute souvent par des cycles plus irréguliers et peut s'accompagner de bouffées de chaleur, sueurs nocturnes, troubles du sommeil, variations de l'humeur, difficultés de concentration ou symptômes génito-urinaires. Après 45 ans, avec des signes typiques, le diagnostic est le plus souvent clinique : un dosage hormonal systématique n'est généralement pas nécessaire.",
  answer: "La périménopause, souvent appelée préménopause, correspond à la période de transition précédant l'arrêt définitif des règles. Elle survient en moyenne autour de 47 ans et dure souvent plusieurs années, mais l'âge de début, la durée et les symptômes varient beaucoup. Les cycles peuvent devenir plus courts ou plus longs et les règles plus ou moins abondantes. Bouffées de chaleur, sueurs nocturnes, sommeil perturbé, fatigue, irritabilité ou anxiété, brouillard mental, migraines, sécheresse vaginale, baisse du désir, symptômes urinaires et douleurs articulaires peuvent également apparaître. Aucun de ces symptômes n'est à lui seul spécifique. La ménopause n'est confirmée qu'après 12 mois consécutifs sans règles. Chez une femme de plus de 45 ans avec un tableau typique, les recommandations privilégient l'évaluation clinique : les dosages de FSH ou d'autres hormones ne sont pas systématiques car les concentrations fluctuent pendant la transition. Une situation avant 40 ans, très précoce ou atypique nécessite en revanche une évaluation spécifique. La périménopause n'est pas une maladie et n'est pas en elle-même inquiétante, mais tout symptôme ne doit pas lui être automatiquement attribué.",
  practical: [
    "Consulter si les symptômes altèrent le sommeil, la sexualité, l'humeur ou la qualité de vie : des prises en charge existent et doivent être adaptées individuellement.",
    "Des saignements très abondants, inhabituels, entre les règles ou après un rapport nécessitent une évaluation plutôt que d'être attribués automatiquement à la périménopause.",
    "Avant 40 ans, un arrêt ou une forte perturbation des règles avec symptômes évocateurs justifie un bilan médical spécifique.",
    "Une grossesse reste possible pendant la périménopause : une contraception reste nécessaire tant que la ménopause n'est pas établie si une grossesse n'est pas souhaitée."
  ],
  evidenceSummary: "Consensus français : la périménopause est définie par les modifications du cycle et/ou l'apparition de symptômes climatériques précédant la ménopause. Chez les femmes d'âge habituel avec présentation typique, le diagnostic est essentiellement clinique ; les dosages hormonaux ne sont pas systématiques. Les symptômes gênants et les présentations atypiques doivent faire l'objet d'une évaluation individualisée.",
  keywords: ["préménopause", "premenopause", "périménopause", "perimenopause", "ménopause", "bouffées de chaleur", "sueurs nocturnes", "règles irrégulières", "cycles irréguliers", "FSH", "hormones", "brouillard mental", "sécheresse vaginale", "libido", "45 ans", "47 ans", "contraception"],
  sourceIds: ["CNGOF_GEMVI_MENOPAUSE_RPC", "CNGOF_MENOPAUSE_PUBLIC", "AMELI_PERIMENOPAUSE_2026", "AMELI_MENOPAUSE_DIAGNOSTIC_2026", "HAS_THM_2025"],
  verifiedAt: "2026-08-20",
  nextAuditAt: "2026-11-20",
  auditStatus: "audited"
});

