/* MACA Santé — Cholestérol : 3 fiches validées le 23/08/2026. Audit trimestriel : 23/11/2026.
   Publication canonique : ces fiches alimentent directement window.healthQuestions. */
(function(){
 const cards=[
 {id:'cholesterol-reduire-sans-medicament',category:'Cœur & prévention',title:'Comment réduire mon cholestérol sans médicament ?',keywords:'cholestérol cholesterol LDL alimentation régime activité physique sport poids graisses saturées fibres médicament statine',answer:'Le mode de vie peut contribuer à diminuer le LDL-cholestérol et reste utile quel que soit le niveau de risque cardiovasculaire. Les mesures les plus importantes sont de réduire les graisses saturées (notamment charcuteries, viandes grasses, beurre, crème, certains produits industriels), de privilégier les huiles végétales, les fruits à coque, les légumes, fruits, légumineuses et céréales complètes, et d’avoir une activité physique régulière. En cas de surpoids, une perte de poids peut aussi améliorer le profil lipidique. L’arrêt du tabac réduit surtout le risque cardiovasculaire global. Ces mesures ne remplacent cependant pas un traitement lorsqu’il est indiqué : la décision dépend du taux de LDL mais surtout du risque cardiovasculaire global.',watch:'Un LDL élevé ne se juge pas isolément. Les antécédents cardiovasculaires, le diabète, la pression artérielle, le tabagisme, l’âge, la fonction rénale et certains facteurs familiaux modifient le niveau de risque et donc l’objectif de LDL.',source:'European Society of Cardiology / European Atherosclerosis Society · Dyslipidaemias 2025',url:'https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/dyslipidaemias/',verifiedAt:'23/08/2026',nextAuditAt:'23/11/2026',validationStatus:'VALIDATED',auditIntervalMonths:3,evidenceStatus:'Recommandations européennes actualisées 2025'},
 {id:'levure-riz-rouge-cholesterol-efficace',category:'Cœur & prévention',title:'La levure de riz rouge est-elle vraiment efficace contre le cholestérol ?',keywords:'levure riz rouge cholestérol cholesterol LDL monacoline K lovastatine complément alimentaire naturel statine',answer:'Oui, certains produits à base de levure de riz rouge peuvent diminuer le LDL-cholestérol, car ils contiennent de la monacoline K, une substance chimiquement identique à la lovastatine, une statine. Mais cela ne signifie pas qu’ils constituent une alternative naturelle sans risque. La quantité de monacoline peut varier selon les produits et des effets indésirables musculaires ou hépatiques ainsi que des interactions médicamenteuses sont possibles. Les recommandations européennes 2025 ne recommandent pas les compléments alimentaires pour réduire le LDL et le risque cardiovasculaire, faute de preuve suffisante d’un bénéfice clinique avec une sécurité satisfaisante.',watch:'Ne pas associer de sa propre initiative levure de riz rouge et statine. Une intolérance à une statine ne signifie pas que la levure de riz rouge sera mieux tolérée, puisque la monacoline K agit comme une statine.',source:'ANSES · Levure de riz rouge ; ESC/EAS · Dyslipidémies 2025',url:'https://www.anses.fr/system/files/NUT2012sa0228.pdf',verifiedAt:'23/08/2026',nextAuditAt:'23/11/2026',validationStatus:'VALIDATED',auditIntervalMonths:3,evidenceStatus:'ANSES croisée avec recommandations ESC/EAS 2025'},
 {id:'statines-dangereuses',category:'Médicaments',title:'Les statines sont-elles dangereuses ?',keywords:'statines statine danger dangereux effets secondaires douleurs musculaires foie diabète cholestérol cholesterol LDL atorvastatine rosuvastatine pravastatine simvastatine',answer:'Non, les statines ne sont pas considérées comme dangereuses lorsqu’elles sont prescrites à bon escient et surveillées de façon adaptée. Elles font partie des traitements les mieux étudiés pour diminuer le LDL-cholestérol et réduisent le risque d’événements cardiovasculaires chez les personnes pour lesquelles elles sont indiquées. Des effets indésirables existent : les symptômes musculaires sont les plus connus, tandis que les atteintes musculaires graves sont rares. Des anomalies hépatiques peuvent survenir et le risque de diabète augmente légèrement chez certaines personnes prédisposées. Le bénéfice attendu dépend du risque cardiovasculaire initial : plus ce risque est élevé, plus le bénéfice absolu du traitement est important.',watch:'Des douleurs musculaires sous statine ne doivent pas conduire automatiquement à abandonner définitivement tout traitement. Il faut rechercher d’autres causes, vérifier les interactions et, selon la situation, adapter la dose, changer de statine ou envisager une autre stratégie hypolipémiante avec le médecin.',source:'European Society of Cardiology / European Atherosclerosis Society · Dyslipidaemias 2025 ; Haute Autorité de Santé',url:'https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/dyslipidaemias/',verifiedAt:'23/08/2026',nextAuditAt:'23/11/2026',validationStatus:'VALIDATED',auditIntervalMonths:3,evidenceStatus:'Recommandations ESC/EAS 2025 croisées avec HAS'}
 ];
 const existing=new Set((window.healthQuestions||[]).map(x=>x.id));
 window.healthQuestions=[...(window.healthQuestions||[]),...cards.filter(c=>!existing.has(c.id))];
 /* Compatibilité transitoire avec les lecteurs historiques ; app.js déduplique par titre avant rendu. */
 window.extraAuditedQuestions=[...(window.extraAuditedQuestions||[]),...cards.filter(c=>!(window.extraAuditedQuestions||[]).some(x=>x.id===c.id))];
})();

;

