// MACA Santé — Seniors / prévention cognitive + alimentation LDL — validation éditoriale 25/08/2026
window.extraAuditedQuestions = [...(window.extraAuditedQuestions || []),
{id:'prevenir-declin-cognitif-vieillissant',category:'Seniors',title:'Peut-on prévenir le déclin cognitif en vieillissant ?',keywords:'senior mémoire déclin cognitif vieillissement démence Alzheimer prévention activité physique audition vision hypertension diabète sommeil lien social FINGER POINTER',answer:'On ne peut pas empêcher tout vieillissement de la mémoire ni prévenir toutes les démences. En revanche, agir sur plusieurs facteurs de santé au cours de la vie peut réduire le risque de déclin cognitif et contribuer à préserver les capacités cérébrales. Les données actuelles soutiennent surtout une approche globale : rester physiquement actif, contrôler l’hypertension, le diabète et les autres facteurs de risque cardiovasculaire, ne pas fumer, limiter l’excès d’alcool, préserver l’audition et la vision, maintenir des activités intellectuelles et des relations sociales, avoir une alimentation équilibrée et prendre en charge une dépression lorsqu’elle existe. Les essais FINGER puis US POINTER soutiennent l’intérêt d’interventions multidomaines plutôt que d’un exercice ou d’un aliment isolé.',watch:'Lire, apprendre, jouer ou faire des mots croisés peuvent participer à la stimulation cognitive, mais aucun exercice cérébral isolé ne garantit la prévention d’une démence. Une plainte de mémoire nouvelle, progressive ou ayant un retentissement sur la vie quotidienne mérite d’être évaluée plutôt que simplement attribuée à l’âge.',source:'HAS · Assurance Maladie · données gériatriques françaises / SFGG · Lancet Commission 2024 · FINGER · US POINTER',sources:[{label:'HAS — Activité physique et personne âgée',url:'https://www.has-sante.fr/upload/docs/application/pdf/2019-07/app_248_ref_aps_pa_vf.pdf'},{label:'HAS — Maladie d’Alzheimer : diagnostiquer tôt',url:'https://www.has-sante.fr/jcms/c_2851128/fr/maladie-d-alzheimer-et-maladies-apparentees-diagnostiquer-tot-pour-mettre-en-place-un-parcours-de-soins-et-d-accompagnement-adapte'},{label:'PubMed — Lancet Commission dementia prevention 2024',url:'https://pubmed.ncbi.nlm.nih.gov/39096926/'},{label:'PubMed — FINGER randomized trial',url:'https://pubmed.ncbi.nlm.nih.gov/25771249/'},{label:'PubMed — US POINTER randomized trial',url:'https://pubmed.ncbi.nlm.nih.gov/40720610/'},{label:'Assurance Maladie — Ameli',url:'https://www.ameli.fr/'}],url:'https://pubmed.ncbi.nlm.nih.gov/39096926/',verifiedAt:'25/08/2026',nextAuditAt:'25/11/2026',auditIntervalMonths:3,validationStatus:'VALIDATED',evidenceStatus:'VALIDÉ — HAS + données gériatriques + Lancet 2024 + essais randomisés FINGER/US POINTER'},
{id:'aliments-augmentent-ldl-cholesterol',category:'Santé au quotidien',title:'Quels aliments font réellement augmenter le LDL-cholestérol ?',keywords:'LDL cholestérol alimentation acides gras saturés trans beurre crème fromage charcuterie viande grasse huile coco palme viennoiseries biscuits fritures œufs',answer:'Le LDL-cholestérol est surtout influencé par la qualité des graisses consommées. Les aliments riches en acides gras saturés peuvent augmenter le LDL lorsqu’ils sont consommés en quantité importante : beurre, crème, certaines charcuteries et viandes grasses, fromages et produits riches en graisses de coco ou de palme. Les acides gras trans industriels ont également un effet défavorable sur le LDL et le risque cardiovasculaire. À l’inverse, remplacer une partie des graisses saturées par des graisses insaturées — huiles de colza ou d’olive, noix et autres fruits à coque, poissons — est généralement plus favorable au profil lipidique. L’effet d’un aliment isolé dépend donc aussi de ce qu’il remplace dans l’alimentation.',watch:'Le cholestérol contenu dans les aliments n’est pas exactement la même chose que le cholestérol sanguin : chez beaucoup de personnes, les acides gras saturés ont davantage d’influence sur le LDL que le seul cholestérol alimentaire. Il n’est donc pas pertinent de résumer la prévention à « supprimer les œufs ». En cas de LDL très élevé, d’hypercholestérolémie familiale ou de risque cardiovasculaire important, l’alimentation reste utile mais peut ne pas suffire à atteindre l’objectif de LDL. Les recommandations ESC/EAS 2025 ne recommandent pas les compléments alimentaires ou vitamines pour réduire le LDL et le risque cardiovasculaire.',source:'ANSES · HAS · ESC/EAS dyslipidémies 2019 + Focused Update 2025',sources:[{label:'ANSES — Acides gras trans : risques et effets sur le LDL',url:'https://www.anses.fr/fr/system/files/NUT-Ra-AGtrans.pdf'},{label:'HAS — prévention cardiovasculaire et limitation des acides gras saturés',url:'https://www.has-sante.fr/upload/docs/application/pdf/2025-02/indicateurs_de_pratique_clinique_idm_2012.pdf'},{label:'ESC — 2019 ESC/EAS Guidelines on dyslipidaemias',url:'https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/dyslipidaemias-management/'},{label:'ESC — 2025 Focused Update of ESC/EAS dyslipidaemia guidelines',url:'https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/dyslipidaemias/'}],url:'https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/dyslipidaemias/',verifiedAt:'25/08/2026',nextAuditAt:'25/11/2026',auditIntervalMonths:3,validationStatus:'VALIDATED',evidenceStatus:'VALIDÉ — ANSES + HAS + ESC/EAS ; priorité à la réduction/remplacement des graisses saturées et trans'}
];
;

