window.extraAuditedQuestions = [...(window.extraAuditedQuestions || []),
{id:'migraine-que-faire',category:'Santé au quotidien',title:'J’ai des migraines : que puis-je faire ?',keywords:'migraine migraines mal de tête céphalée aura triptan AINS CGRP gepant gépant anticorps monoclonal atogépant rimegepant eptinezumab topiramate nausées lumière SFEMC neurologie',answer:'La migraine est une maladie neurologique fréquente. Elle provoque des crises de maux de tête souvent pulsatiles, fréquemment d’un seul côté, aggravées par l’activité physique et parfois accompagnées de nausées, d’une gêne à la lumière ou au bruit. Certaines personnes présentent une aura, le plus souvent visuelle. Pendant une crise, le traitement doit généralement être pris tôt : les AINS peuvent être utilisés lorsqu’ils sont adaptés à la personne et les triptans sont des traitements spécifiques de référence lorsqu’ils sont indiqués. Des habitudes régulières — sommeil, activité physique, repas — et un agenda des migraines peuvent aider à repérer les facteurs associés aux crises et à suivre leur fréquence.',watch:'Lorsque les migraines sont fréquentes ou invalidantes, un traitement préventif peut être proposé. Aux traitements classiques se sont ajoutés des traitements spécifiquement développés contre la migraine ciblant le CGRP ou son récepteur : anticorps monoclonaux et gépants. Ils ont profondément renouvelé la prévention de la migraine ; leur place concrète dépend de la situation, des traitements déjà essayés et des conditions d’accès en France. Le position paper français actualisé en 2024 intègre notamment l’eptinézumab, le rimégépant et l’atogépant. Le topiramate a des restrictions importantes chez les femmes en âge de procréer et est contre-indiqué pendant la grossesse dans la prévention de la migraine. Une consommation trop fréquente de traitements de crise peut entretenir des céphalées. Un mal de tête brutal maximal d’emblée, très inhabituel, associé à un déficit neurologique, une confusion, une fièvre avec altération de l’état général ou survenant dans un contexte inhabituel nécessite une évaluation médicale rapide.',source:'SFEMC — position française actualisé 2024 · HAS/Assurance Maladie · Lancet Neurology 2026',sources:[{label:'PubMed — French Society for the Study of Migraine and Headache, position paper update 2024',url:'https://pubmed.ncbi.nlm.nih.gov/39406556/'},{label:'Société Française de Neurologie',url:'https://www.sf-neuro.org/'},{label:'SFEMC — Société Française d’Études des Migraines et Céphalées',url:'https://sfemc.fr/'},{label:'PubMed — Lancet Neurology 2026, migraine treatment advances',url:'https://pubmed.ncbi.nlm.nih.gov/41722594/'},{label:'Assurance Maladie — Migraine',url:'https://www.ameli.fr/assure/sante/themes/migraine'}],url:'https://pubmed.ncbi.nlm.nih.gov/39406556/',verifiedAt:'25/08/2026',nextAuditAt:'25/11/2026',auditIntervalMonths:3,validationStatus:'VALIDATED',evidenceStatus:'VALIDÉ — SFEMC 2024 + neurologie française + données internationales 2026'}
];
;

