window.extraAuditedQuestions = [...(window.extraAuditedQuestions || []),
{id:'prise-poids-sans-raison',category:'Santé quotidienne',title:'Pourquoi je prends du poids alors que je ne mange pas plus ?',keywords:'prise de poids métabolisme masse musculaire sommeil thyroide ménopause médicaments',answer:'Une prise de poids peut avoir plusieurs causes : diminution de la masse musculaire, baisse de l’activité physique, sommeil insuffisant, changements hormonaux ou certains médicaments. Elle ne signifie pas forcément que l’alimentation est seule en cause.',watch:'Une prise de poids rapide, des œdèmes, un essoufflement ou une fatigue inhabituelle nécessitent un avis médical. Le bilan dépend du contexte clinique.',source:'HAS · Société Française d’Endocrinologie · Société Française de Nutrition',verifiedAt:'26/08/2026',validationStatus:'VALIDATED'},
{id:'palpitations-quand-consulter',category:'Cœur',title:'Palpitations : quand faut-il consulter ?',keywords:'palpitations coeur extrasystoles arythmie fibrillation atriale ECG',answer:'Les palpitations correspondent à la sensation de sentir son cœur battre plus vite, plus fort ou de façon irrégulière. Elles sont souvent bénignes mais peuvent parfois révéler un trouble du rythme.',watch:'Un avis médical est nécessaire en cas de malaise, douleur thoracique, essoufflement, perte de connaissance ou rythme très rapide prolongé.',source:'Société Française de Cardiologie · ESC · EHRA',verifiedAt:'26/08/2026',validationStatus:'VALIDATED'},
{id:'sommeil-apres-60-ans',category:'Senior',title:'Sommeil après 60 ans : ce qui change vraiment',keywords:'sommeil senior insomnie apnée sommeil vieillissement',answer:'Le sommeil évolue avec l’âge : il peut devenir plus fragmenté, mais un sommeil non réparateur n’est pas une fatalité. Il faut rechercher notamment une insomnie ou une apnée du sommeil.',watch:'Une somnolence importante la journée, des pauses respiratoires nocturnes ou une insomnie persistante justifient une évaluation.',source:'SFRMS · Société Française de Gériatrie et Gérontologie · HAS',verifiedAt:'26/08/2026',validationStatus:'VALIDATED'},
{id:'vertiges-causes',category:'Santé quotidienne',title:'Vertiges : les causes fréquentes et les signes d’alerte',keywords:'vertige oreille interne VPPB neurologie équilibre',answer:'Le mot vertige décrit plusieurs sensations : impression que tout tourne, instabilité ou malaise. La cause dépend de la description précise des symptômes.',watch:'Une faiblesse d’un côté du corps, un trouble de la parole, un nouveau mal de tête intense ou une perte de connaissance nécessitent un avis urgent.',source:'SFORL · Société Française de Neurologie · HAS',verifiedAt:'26/08/2026',validationStatus:'VALIDATED'},
{id:'crampes-musculaires-causes',category:'Santé quotidienne',title:'Crampes musculaires : causes et solutions',keywords:'crampes muscle magnésium hydratation sport',answer:'Les crampes sont des contractions musculaires involontaires souvent bénignes. Elles peuvent être favorisées par l’effort, la fatigue musculaire ou certains contextes médicaux.',watch:'Une supplémentation en magnésium n’est pas systématique. Des crampes fréquentes ou atypiques peuvent nécessiter une recherche de cause.',source:'HAS · Société Française de Médecine Générale · Médecine du sport',verifiedAt:'26/08/2026',validationStatus:'VALIDATED'}
];
