/* ===== MACA BUNDLE SOURCE: structured-backlog-compat.js ===== */
// Compatibility bridge: converts structured audited cards into the legacy question shape used by app.js.
(() => {
  const structured = [
    ...(Array.isArray(window.SANTEJUSTE_BACKLOG_AUDITED) ? window.SANTEJUSTE_BACKLOG_AUDITED : []),
    ...(Array.isArray(window.MACA_BACKLOG_AUDITED) ? window.MACA_BACKLOG_AUDITED : [])
  ];
  if (!structured.length) return;
  const sourceRegistry = window.SANTEJUSTE_SOURCE_REGISTRY || window.MACA_SOURCE_REGISTRY || {};
  const existing = new Set((window.extraAuditedQuestions || []).map(q => q.id));
  const seen = new Set(existing);
  const converted = structured.filter(q => {
    const id = String(q?.id || '').trim();
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return true;
  }).map(q => {
    const sources = (q.sourceIds || []).map(id => sourceRegistry[id]).filter(Boolean);
    const sourceLabel = sources.map(s => s.name).join(' · ') || 'Sources vérifiées';
    const firstUrl = sources[0]?.url || '#';
    const verified = q.verifiedAt ? q.verifiedAt.split('-').reverse().join('/') : '20/08/2026';
    return {
      id: q.id,
      category: q.category,
      title: q.question || q.title,
      keywords: Array.isArray(q.keywords) ? q.keywords.join(' ') : (q.keywords || ''),
      answer: q.shortAnswer || q.answer || '',
      watch: Array.isArray(q.practical) ? q.practical.join(' ') : (q.watch || ''),
      source: sourceLabel,
      url: firstUrl,
      verifiedAt: verified,
      evidenceStatus: q.evidenceSummary || 'Sources croisées'
    };
  });
  window.extraAuditedQuestions = [...(window.extraAuditedQuestions || []), ...converted];
})();

;

/* ===== MACA BUNDLE SOURCE: migration-cancer-editorial-2026-09-07.js ===== */
/* MACA Santé — Cancer V2 — enrichissement pédagogique à fond médical constant.
 * 10 fiches existantes uniquement. Aucun ajout, aucun changement d'ID, catégorie, keywords ou métadonnée d'audit.
 * Le contenu ci-dessous développe exclusivement les éléments déjà validés dans les fiches Cancer sources.
 */
(function(){
  'use strict';
  const updates={
    'cancer-biopsie-liquide-ctdna':{
      answer:"Dans la plupart des situations, une simple prise de sang ne permet pas de savoir à elle seule si une personne a un cancer.\n\nIl existe cependant des analyses particulières, appelées « biopsies liquides », capables de rechercher dans le sang des éléments provenant de la tumeur, notamment de l’ADN tumoral circulant. Elles sont déjà utiles dans certaines situations chez des patients ayant un cancer connu.",
      detail:"Une tumeur peut libérer dans le sang de très petites quantités de matériel génétique. Une partie de cet ADN circulant peut provenir des cellules cancéreuses : on parle alors d’ADN tumoral circulant, ou ctDNA. L’idée de la biopsie liquide est d’analyser ce matériel à partir d’un prélèvement sanguin, sans prélever directement un fragment de la tumeur.\n\nChez certains patients ayant déjà un cancer, cette analyse peut rechercher des anomalies moléculaires présentes dans la tumeur. Lorsqu’une anomalie correspond à une cible thérapeutique connue, cette information peut contribuer au choix d’une thérapie ciblée. Cette approche peut notamment être utile lorsque la biopsie de la tumeur est difficile à réaliser.\n\nLa biopsie liquide ne remplace cependant pas automatiquement la biopsie classique. Toutes les tumeurs ne libèrent pas la même quantité d’ADN dans le sang et un prélèvement peut ne pas retrouver une anomalie pourtant présente dans la tumeur. Un résultat négatif peut donc conduire à analyser directement le tissu tumoral lorsque cela est nécessaire.\n\nLe ctDNA est aussi étudié comme marqueur de maladie résiduelle moléculaire. Après un traitement, des traces d’ADN tumoral peuvent parfois être détectées alors que la maladie n’est pas visible par les examens d’imagerie. Cela ouvre des perspectives pour repérer plus précocement certaines récidives et mieux adapter la surveillance.\n\nIl faut néanmoins distinguer ces usages chez une personne dont le cancer est connu d’un dépistage dans la population générale. Les performances et l’utilité du ctDNA varient selon le type de cancer et la situation clinique. Les travaux actuels ne permettent donc pas d’en faire un test sanguin unique capable de dépister ou d’exclure tous les cancers.",
      watchTitle:"À ne pas confondre",
      watch:"Une biopsie liquide n’est pas aujourd’hui un « test sanguin universel du cancer ». Un résultat négatif ne permet donc pas, à lui seul, d’exclure un cancer. Son interprétation dépend du cancer recherché, de la situation et de la question posée.",
      source:"GFCO — recommandations nationales françaises sur l’ADN tumoral circulant. ASCO — guideline ctDNA 2026. ESMO Precision Medicine Working Group — recommandations sur les analyses de ctDNA."
    },
    'cancer-adc-anticorps-conjugues':{
      answer:"On peut les comprendre comme une manière de transporter un médicament anticancéreux plus directement vers certaines cellules tumorales.\n\nUn ADC associe un anticorps qui reconnaît une cible présente sur la cellule cancéreuse et une substance capable de la détruire.",
      detail:"ADC signifie antibody-drug conjugate, ou anticorps conjugué à un médicament. Un ADC réunit trois éléments : un anticorps capable de reconnaître une cible présente sur certaines cellules tumorales, un système de liaison et une molécule cytotoxique.\n\nL’anticorps joue en quelque sorte le rôle de véhicule. Il reconnaît la cible et transporte avec lui la molécule anticancéreuse. Cette stratégie cherche ainsi à mieux diriger le traitement vers les cellules qui expriment la cible plutôt qu’à exposer de la même manière toutes les cellules de l’organisme.\n\nCette idée explique l’expression parfois utilisée de « chimiothérapie ciblée », même si elle simplifie un mécanisme plus complexe. Les ADC sont désormais de véritables traitements standards dans plusieurs cancers, notamment certains cancers du sein, du poumon, gynécologiques, digestifs ou urothéliaux.\n\nAvant d’utiliser certains de ces médicaments, les caractéristiques biologiques de la tumeur sont étudiées afin de savoir si la cible recherchée est présente. Mais cette présence ne suffit pas toujours à prédire parfaitement la réponse. La quantité de cible, la biologie de la tumeur et différents mécanismes de résistance peuvent également intervenir.\n\nLes ADC illustrent donc l’évolution de l’oncologie vers des traitements davantage guidés par les caractéristiques de la tumeur. Ils ne remplacent pas pour autant toutes les autres approches : selon la maladie et son stade, ils peuvent s’intégrer à une stratégie comprenant chirurgie, radiothérapie, chimiothérapie, immunothérapie ou autres traitements.",
      watchTitle:"À savoir",
      watch:"« Ciblé » ne veut pas dire sans effets indésirables. Une partie du médicament peut également affecter des tissus sains et chaque ADC possède ses propres toxicités. La présence de la cible sur la tumeur ne garantit pas non plus, à elle seule, l’efficacité du traitement.",
      source:"Cancer — standards actuels des antibody-drug conjugates, 2026. Cancer Cell — ADC et oncologie de précision, 2026. ESMO Open — position statement sur les ADC, 2026."
    },
    'cancer-oncogenetique-famille':{
      answer:"Pas forcément. La plupart des cancers ne sont pas dus à une prédisposition génétique héréditaire.\n\nMais certains antécédents familiaux peuvent justifier une consultation d’oncogénétique : plusieurs proches atteints, cancers survenus jeunes ou association de certains types de cancers dans une même famille.",
      detail:"Un cancer apparaît lorsque des cellules accumulent des anomalies qui perturbent leur fonctionnement. Le plus souvent, ces anomalies sont acquises au cours de la vie et ne sont pas transmises aux enfants. C’est pourquoi avoir un cancer ne signifie pas automatiquement qu’il existe une prédisposition héréditaire dans la famille.\n\nDans certaines familles, en revanche, une variation génétique constitutionnelle peut augmenter le risque de développer certains cancers. Pour évaluer cette possibilité, la consultation d’oncogénétique ne se limite pas à compter le nombre de cancers : elle reconstitue l’histoire familiale, le lien de parenté entre les personnes atteintes, le type de cancer et surtout l’âge auquel il est apparu.\n\nÀ partir de ces éléments, l’équipe évalue s’il existe suffisamment d’arguments pour proposer un test génétique. Le test cherche alors une variation constitutionnelle, c’est-à-dire présente dans les cellules de l’organisme et susceptible d’être transmise.\n\nLorsqu’une prédisposition est identifiée, le résultat peut modifier la surveillance de la personne testée. Il peut également avoir des conséquences pour certains membres de sa famille, puisque la question posée concerne alors un risque héréditaire et non uniquement les caractéristiques de la tumeur d’une seule personne.\n\nIl faut enfin distinguer cette démarche des analyses moléculaires réalisées directement sur une tumeur. Une tumeur peut posséder une anomalie génétique apparue uniquement dans les cellules cancéreuses. Cette anomalie dite somatique peut aider à caractériser le cancer ou à choisir un traitement, sans être pour autant présente dans le reste de l’organisme ni transmissible dans la famille.",
      watchTitle:"Un point important",
      watch:"Un test moléculaire effectué sur la tumeur et un test génétique constitutionnel ne répondent pas exactement à la même question. Une anomalie trouvée uniquement dans la tumeur n’est donc pas nécessairement héréditaire.",
      source:"Institut national du cancer — oncogénétique et dispositif français. ASCO — germline genetic testing guideline, 2024. ESMO — recommandations génétiques en oncologie, 2025."
    },
    'cancer-remission-guerison':{
      answer:"Pas exactement.\n\nUne rémission complète signifie que les examens disponibles ne retrouvent plus de signe détectable du cancer. C’est une excellente nouvelle, mais cela ne permet pas toujours de parler immédiatement de guérison.",
      detail:"Après un traitement, les médecins évaluent la réponse du cancer à l’aide des examens adaptés à la maladie. Lorsque les examens disponibles ne retrouvent plus de signe détectable du cancer, on peut parler de rémission complète. Cela décrit donc ce que les outils actuels permettent d’observer à ce moment-là.\n\nCette notion ne signifie pas nécessairement qu’il est possible d’affirmer immédiatement que toutes les cellules cancéreuses ont disparu. Des cellules peuvent parfois persister en quantité trop faible pour être détectées. C’est l’une des raisons pour lesquelles une surveillance est maintenue après les traitements même lorsque la réponse obtenue est excellente.\n\nLe risque de récidive n’est pas identique pour tous les cancers. Il dépend notamment du type de cancer, de son stade, de ses caractéristiques biologiques et de la réponse obtenue au traitement. Avec le temps, si la maladie ne réapparaît pas, ce risque diminue généralement et il peut devenir possible de parler de guérison.\n\nIl n’existe donc pas un délai unique applicable à toutes les situations. La règle souvent évoquée des « cinq ans » est un repère statistique historique, mais elle ne constitue pas une frontière universelle entre rémission et guérison. Certains cancers ont un risque de récidive qui diminue rapidement, tandis que pour d’autres la surveillance doit rester prolongée.\n\nLe suivi après cancer sert ainsi à surveiller une éventuelle récidive selon les modalités prévues pour le cancer concerné, mais aussi à prendre en compte les conséquences des traitements et l’état de santé général. Une rémission complète constitue une étape majeure du parcours sans rendre inutile le suivi prévu.",
      watchTitle:"À savoir",
      watch:"La rémission complète est une excellente nouvelle, mais elle n’interrompt pas automatiquement la surveillance. Le calendrier et la durée du suivi dépendent du cancer et de la situation individuelle.",
      source:"Institut national du cancer — Cancer Info : rémission, guérison et suivi. Gustave Roussy — information patient sur l’après-cancer."
    },
    'cancer-metastases-definition':{
      answer:"Une métastase est un nouveau foyer de cellules cancéreuses qui s’est développé à distance du cancer d’origine.\n\nPar exemple, si un cancer du sein se propage dans un os, il s’agit d’une métastase du cancer du sein dans l’os et non d’un nouveau « cancer de l’os ».",
      detail:"Un cancer commence dans un organe ou un tissu : c’est la tumeur d’origine, aussi appelée tumeur primitive. Au cours de l’évolution de certains cancers, des cellules peuvent se détacher de cette tumeur, circuler dans l’organisme par le sang ou la lymphe puis s’implanter à distance. Lorsqu’elles forment un nouveau foyer tumoral, on parle de métastase.\n\nLes cellules d’une métastase restent liées au cancer dont elles proviennent. Une métastase osseuse d’un cancer du sein reste donc constituée de cellules du cancer du sein ; elle n’est pas assimilée à un cancer primitif de l’os. Cette distinction est importante car le traitement dépend notamment du cancer d’origine et de ses caractéristiques biologiques.\n\nTous les cancers n’ont pas la même capacité à produire des métastases et les organes concernés ne sont pas les mêmes selon la tumeur d’origine. La présence de métastases modifie généralement le stade de la maladie et conduit à adapter la stratégie thérapeutique.\n\nLe mot « métastatique » recouvre cependant des situations très différentes. Le nombre de foyers, leur localisation, les caractéristiques biologiques du cancer et les traitements disponibles comptent dans la prise en charge. Les possibilités thérapeutiques ont également évolué et peuvent associer, selon les situations, traitements agissant dans l’ensemble de l’organisme et traitements dirigés vers certaines zones.\n\nLe terme décrit donc l’extension du cancer mais ne résume pas à lui seul toute la situation d’une personne. Pour comprendre ce qu’il signifie concrètement, il faut le replacer dans le type de cancer, son bilan d’extension et la stratégie proposée.",
      watchTitle:"À savoir",
      watch:"Le mot « métastatique » décrit une extension du cancer. Il ne permet pas, à lui seul, de prévoir précisément l’évolution d’une personne ni de résumer les possibilités de traitement.",
      source:"Institut national du cancer — Cancer Info. ESMO — information destinée aux patients sur les cancers métastatiques."
    },
    'cancer-nouveaux-traitements-2026':{
      answer:"Il n’existe pas un nouveau traitement unique qui remplacerait les autres.\n\nLa chirurgie, la radiothérapie et la chimiothérapie restent essentielles, mais l’oncologie dispose aujourd’hui de traitements supplémentaires : thérapies ciblées, immunothérapies, anticorps conjugués, anticorps bispécifiques et certaines thérapies cellulaires, selon les cancers.",
      detail:"Le traitement d’un cancer n’est plus déterminé uniquement par le nom de l’organe atteint. Le type de cancer, son stade et son extension restent essentiels, mais l’analyse de la tumeur peut aussi mettre en évidence des caractéristiques biologiques ou moléculaires utiles pour choisir certains traitements.\n\nDeux cancers développés dans le même organe peuvent ainsi être biologiquement différents. Lorsqu’une caractéristique particulière — souvent appelée biomarqueur — peut être reliée à un médicament, elle peut aider à sélectionner une thérapie ciblée ou une autre stratégie adaptée. C’est l’un des principes de la médecine de précision.\n\nParallèlement, l’immunothérapie a transformé le traitement de plusieurs cancers en permettant, dans certaines situations, au système immunitaire de mieux combattre les cellules tumorales. D’autres approches se sont développées, comme les anticorps conjugués qui transportent une molécule cytotoxique vers des cellules exprimant une cible, les anticorps bispécifiques ou certaines thérapies cellulaires dans des indications précises.\n\nCes innovations ne rendent pas la chirurgie, la radiothérapie ou la chimiothérapie obsolètes. Les traitements classiques restent fondamentaux et les nouvelles approches peuvent les compléter, être utilisées avec eux ou intervenir à différents moments de la maladie.\n\nLe mot « nouveau » ne signifie donc pas qu’un traitement convient à tous les cancers ni qu’il est automatiquement supérieur aux traitements plus anciens. Son intérêt dépend de l’indication, des caractéristiques de la tumeur et des résultats obtenus dans les études cliniques. L’évolution actuelle de l’oncologie correspond surtout à un arsenal thérapeutique plus diversifié et à une sélection de plus en plus précise des traitements lorsqu’un biomarqueur ou une caractéristique de la maladie le permet.",
      watchTitle:"En pratique",
      watch:"Un traitement innovant n’est pas nécessairement meilleur pour chaque patient. Son intérêt dépend du cancer, de son stade, de ses caractéristiques et des données disponibles pour l’indication concernée.",
      source:"Institut national du cancer — médecine de précision, thérapies ciblées et immunothérapie. ESMO — oncologie de précision. EMA — médicaments anticancéreux et autorisations européennes."
    },
    'cancer-immunotherapie-comment-ca-marche':{
      answer:"Certaines immunothérapies permettent au système immunitaire de mieux reconnaître ou combattre les cellules cancéreuses.\n\nElles ont profondément modifié le traitement de plusieurs cancers, mais elles ne fonctionnent pas chez tous les patients.",
      detail:"Le système immunitaire est capable de reconnaître et d’éliminer des cellules anormales, mais son activité doit aussi être contrôlée pour éviter qu’il n’attaque excessivement les tissus sains. Il possède donc des mécanismes de régulation que l’on peut comparer à des « freins ».\n\nCertaines cellules cancéreuses parviennent à exploiter ces mécanismes pour échapper aux défenses immunitaires. Les points de contrôle immunitaire comme PD-1/PD-L1 ou CTLA-4 participent à cette régulation. Des médicaments appelés inhibiteurs de points de contrôle peuvent bloquer certains de ces freins et permettre aux lymphocytes T d’attaquer plus efficacement la tumeur.\n\nCette stratégie a transformé le traitement de plusieurs cancers, mais elle ne fonctionne pas chez tous les patients. Le type de cancer, sa biologie et différents biomarqueurs peuvent intervenir dans la décision thérapeutique et dans la probabilité de réponse.\n\nLe terme immunothérapie recouvre par ailleurs plusieurs stratégies. Outre les inhibiteurs de points de contrôle, il existe notamment certains anticorps bispécifiques et des thérapies cellulaires comme les CAR-T dans des indications précises. Leur fonctionnement et leurs effets indésirables ne sont pas identiques.\n\nLe principe même de stimuler ou de réorienter l’immunité explique certaines toxicités particulières. Avec les inhibiteurs de points de contrôle, une activation excessive peut provoquer une inflammation d’organes sains. La peau, l’intestin, le foie, les poumons, la thyroïde ou d’autres glandes peuvent notamment être concernés.\n\nL’immunothérapie n’est donc ni une chimiothérapie classique, ni un traitement universel, ni un traitement dépourvu de risques. Elle constitue une famille de traitements dont l’intérêt dépend de la situation oncologique précise.",
      watchTitle:"Quels effets indésirables ?",
      watch:"Un symptôme nouveau pendant une immunothérapie doit être signalé à l’équipe qui suit le traitement. Les effets indésirables immunitaires peuvent concerner différents organes et nécessiter une prise en charge adaptée.",
      source:"Institut national du cancer — immunothérapie et inhibiteurs de points de contrôle. ESMO — recommandations et information patient sur l’immunothérapie. EMA — informations réglementaires des immunothérapies autorisées."
    },
    'cancer-therapies-ciblees-biomarqueurs':{
      answer:"Une thérapie ciblée agit sur une caractéristique particulière de certaines cellules cancéreuses ou sur un mécanisme dont elles ont besoin pour se développer.\n\nIl faut donc parfois analyser la tumeur pour vérifier si la cible recherchée est présente.",
      detail:"Les cellules cancéreuses peuvent présenter des anomalies ou des caractéristiques moléculaires qui participent à leur croissance. Une thérapie ciblée cherche à agir sur l’une de ces caractéristiques ou sur un mécanisme important pour la tumeur.\n\nLorsque l’efficacité d’un médicament dépend d’un biomarqueur, un prélèvement tumoral ou une autre analyse adaptée peut être étudié pour rechercher cette cible. Des anomalies concernant par exemple HER2, EGFR, ALK ou BRAF peuvent guider certains traitements dans des cancers précis. Ces exemples ne sont pas interchangeables : la pertinence d’une anomalie dépend toujours du type de cancer et de la situation.\n\nCette approche explique pourquoi deux personnes ayant un cancer développé dans le même organe peuvent recevoir des traitements différents. Le nom de l’organe reste important, mais les caractéristiques biologiques de la tumeur apportent parfois une information supplémentaire pour choisir le traitement.\n\nLa présence d’une cible ne signifie cependant pas que le médicament sera nécessairement efficace. La tumeur possède de nombreuses caractéristiques et sa réponse dépend de mécanismes complexes. Au cours du temps, les cellules cancéreuses peuvent également évoluer sous la pression du traitement et développer des mécanismes de résistance.\n\nUne nouvelle analyse de la maladie peut alors, dans certaines situations, aider à comprendre cette évolution et conduire à modifier la stratégie thérapeutique. C’est l’un des aspects de la médecine de précision : utiliser les informations biologiques lorsqu’elles ont une utilité démontrée pour orienter la prise en charge.\n\nEnfin, « ciblé » ne signifie pas que seules les cellules cancéreuses peuvent être affectées. Ces médicaments peuvent eux aussi provoquer des effets indésirables, qui dépendent de la cible et du traitement utilisé.",
      watchTitle:"À savoir",
      watch:"Une cible moléculaire n’est utile que dans les cancers et situations où son intérêt est établi. « Thérapie ciblée » ne signifie ni traitement sans toxicité, ni efficacité garantie.",
      source:"Institut national du cancer — thérapies ciblées, biomarqueurs et plateformes de génétique moléculaire. ESMO — médecine de précision. EMA — indications des thérapies ciblées autorisées."
    },
    'cancer-intelligence-artificielle-usages-reels':{
      answer:"L’intelligence artificielle peut aider les professionnels dans certaines tâches : analyser des images, étudier des prélèvements, préparer une radiothérapie ou exploiter de grandes quantités de données.\n\nElle ne remplace pas le médecin et toutes les applications annoncées ne sont pas encore utilisées en pratique courante.",
      detail:"En cancérologie, l’intelligence artificielle désigne un ensemble d’outils capables d’analyser de grandes quantités de données et d’identifier certains motifs. Leur intérêt dépend de la tâche précise pour laquelle ils ont été conçus et validés.\n\nEn imagerie, certains modèles peuvent aider à repérer ou caractériser des anomalies. En anatomopathologie numérique, d’autres peuvent contribuer à l’analyse d’images de prélèvements. Ces outils ont vocation à assister le professionnel dans certaines tâches, pas à supprimer l’interprétation médicale.\n\nLa radiothérapie constitue un autre domaine d’application. Des systèmes d’IA peuvent notamment aider à délimiter automatiquement des organes ou des volumes sur les images, accélérer certaines étapes de planification ou contribuer à l’analyse quantitative des images. L’objectif est souvent de gagner du temps, de standardiser certaines tâches ou d’exploiter des informations difficiles à analyser manuellement.\n\nD’autres modèles sont étudiés pour combiner des données cliniques, d’imagerie ou moléculaires afin de caractériser les tumeurs, d’étudier le pronostic ou de rechercher des facteurs associés à la réponse aux traitements. Une partie importante de ces usages reste toutefois du domaine de la recherche ou nécessite encore des validations supplémentaires avant une utilisation clinique large.\n\nUne bonne performance dans une étude informatique ne suffit pas. Un modèle doit être évalué sur des patients différents de ceux qui ont servi à son développement, et son utilité réelle doit être démontrée dans le contexte où il sera utilisé. Les performances peuvent varier selon les populations, les appareils, les pratiques et la qualité des données.\n\nC’est pourquoi la reproductibilité, les biais, la protection des données et la supervision humaine restent des enjeux centraux. L’IA est donc surtout un nouvel ensemble d’outils d’aide à certaines tâches de la cancérologie, avec des niveaux de maturité très différents selon les applications.",
      watchTitle:"Pourquoi rester prudent ?",
      watch:"Un résultat performant dans une étude ne suffit pas à prouver qu’un outil améliore réellement les soins. Validation externe ou prospective, maîtrise des biais, protection des données et contrôle humain restent essentiels.",
      source:"Institut national du cancer — recherche et médecine de précision. ESMO — travaux sur les données numériques et l’IA en oncologie. Littérature scientifique sur l’IA en radio-oncologie et la radiomique déjà validée dans MACA."
    },
    'cancer-radiotherapie-moderne-precision-reirradiation':{
      answer:"La radiothérapie cherche à délivrer une dose suffisante à la tumeur tout en protégeant autant que possible les tissus sains autour.\n\nLes progrès de l’imagerie et des appareils permettent aujourd’hui d’adapter beaucoup plus précisément la forme et la délivrance des rayonnements.",
      detail:"La radiothérapie utilise des rayonnements pour traiter une zone définie. Avant le traitement, l’équipe détermine précisément le volume à irradier et repère les organes voisins qu’il faut protéger autant que possible. La planification sert ensuite à répartir la dose de manière adaptée à cette anatomie.\n\nLes progrès de l’imagerie guidée permettent de mieux vérifier la position de la zone traitée. La modulation d’intensité, ou IMRT, permet de faire varier la délivrance du rayonnement afin de mieux conformer la dose à la cible. La radiothérapie stéréotaxique utilise une très grande précision pour certaines situations où un traitement très focalisé est recherché.\n\nDans certains cas, la radiothérapie peut aussi être adaptée à des changements observés au cours du traitement : on parle de radiothérapie adaptative. La protonthérapie constitue une autre technique utilisée dans des situations sélectionnées. Toutes ces approches répondent au même objectif général : traiter efficacement la cible tout en limitant autant que possible l’exposition des tissus sains.\n\nCes progrès ont également élargi les possibilités de réirradiation. Une réirradiation consiste à traiter de nouveau une zone déjà irradiée ou proche d’une zone antérieurement traitée. Elle peut être envisagée chez certains patients soigneusement sélectionnés, mais elle nécessite une évaluation particulièrement précise.\n\nLa dose déjà reçue par les tissus, le volume à traiter, le délai depuis le premier traitement et la proximité d’organes sensibles doivent être pris en compte. Les progrès de l’IMRT, de la stéréotaxie, de l’imagerie et de la planification permettent de mieux étudier ces situations, sans faire disparaître les risques liés aux doses cumulées.\n\nLa radiomique et l’intelligence artificielle sont également étudiées pour mieux exploiter les images et personnaliser certaines étapes de la radiothérapie, mais leurs usages ont des niveaux de validation variables.",
      watchTitle:"À savoir",
      watch:"Plus précis ne signifie pas sans risque. La dose, le volume traité et la proximité d’organes sensibles restent déterminants. En cas de réirradiation, l’évaluation des doses déjà reçues et des doses cumulées est essentielle.",
      source:"Institut national du cancer — principes de la radiothérapie. ESTRO/EORTC — consensus sur la réirradiation. Beddok A. et al. — CA Cancer Journal for Clinicians, 2025. Beddok A. et al. — Cancer Radiothérapie, 2024."
    }
  };

  const pools=[window.healthQuestions,window.extraAuditedQuestions].filter(Array.isArray);
  const found=new Set();
  pools.forEach(pool=>pool.forEach(card=>{
    const patch=card&&updates[card.id];
    if(!patch)return;
    Object.assign(card,patch);
    found.add(card.id);
  }));
  const missing=Object.keys(updates).filter(id=>!found.has(id));
  window.MACA_CANCER_V2_MIGRATION={expected:10,matchedIds:[...found],matchedCount:found.size,missing};
  if(missing.length) console.error('[MACA Cancer V2] fiches existantes introuvables :',missing);
})();

;

